pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        address user1 = address(0x123);
        address user2 = address(0x456);
        vm.prank(user1);
        c.getFreeKilo();
        vm.prank(user2);
        c.getFreeKilo();

        vm.warp(block.timestamp + 86400);

        vm.prank(user1);
        c.collectDrugs(user2);

        uint256 referrerClaimed = c.claimedDrugs(user2);

        assertTrue(referrerClaimed > 0, "Referrer should have claimed drugs in correct version");
    }
}
